sys_script_client.script:
function onLoad() {
    var user = g_user.userID;
    var ga = new GlideAjax('populateUserEmailAddress');
    ga.addParam('sysparm_name', 'getaddress');
    ga.addParam('sysparm_user', user);

    ga.getXMLAnswer(processResponse);

    function processResponse(reposnse) {
        g_form.setValue('u_requested_for_email', reposnse); // here you can set the value to any variable you want using g_form.setvalue()alert('response is '+ reposnse )
    }
}
